const base = $('Code - Montar Alunos').first().json;
const raw = String(base.FORMADORES_RAW || '').trim();

function normalizeRawText(text = '') {
  return String(text || '')
    .replace(/\\r\\n/g, '\n')
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\n')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n')
    .trim();
}

function splitLines(text = '') {
  return normalizeRawText(text)
    .split('\n')
    .map(v => v.trim())
    .filter(Boolean);
}

function cleanLine(value = '') {
  return String(value || '')
    .replace(/^[-–•\s]+/, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function isHeaderLine(s) {
  const t = String(s || '').trim().toUpperCase();
  return [
    'FORMADORES:',
    'FORMADORES',
    'FORMADORES EXTERNOS:',
    'FORMADORES EXTERNOS',
    'PROFESSORES:',
    'PROFESSORES',
    'PROFESSORES EXTERNOS:',
    'PROFESSORES EXTERNOS'
  ].includes(t);
}

function parsePerson(rawLine) {
  const value = cleanLine(rawLine);
  if (!value || isHeaderLine(value)) return null;

  let m = value.match(/^(.*?)\s*-\s*([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
  if (m) {
    return { nome: cleanLine(m[1]), email: m[2].trim().toLowerCase() };
  }

  m = value.match(/^(.*?)<\s*([^>]+@[^>]+)\s*>$/);
  if (m) {
    return { nome: cleanLine(m[1]) || m[2].trim(), email: m[2].trim().toLowerCase() };
  }

  m = value.match(/^([A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})$/i);
  if (m) {
    return { nome: m[1].trim(), email: m[1].trim().toLowerCase() };
  }

  return null;
}

const out = [];
const dedup = new Set();

for (const linha of splitLines(raw)) {
  const p = parsePerson(linha);
  if (!p || !p.email) continue;
  if (dedup.has(p.email)) continue;
  dedup.add(p.email);

  out.push({
    json: {
      ...base,
      PROFESSOR_NOME: p.nome,
      PROFESSOR_EMAIL: p.email,
      HORARIO_INICIO: base.INICIO || '',
      HORARIO_FIM: base.TERMINO || '',
      TITULO_CURSO: base['TÍTULO'] || base.curso_nome,
      TEM_FORMADORES: true
    }
  });
}

if (!out.length) {
  return [{
    json: {
      ...base,
      TEM_FORMADORES: false,
      _motivo: raw
        ? 'Nenhum e-mail de formador reconhecido no campo FORMADORES.'
        : 'Curso sem formadores na agenda (ou curso não localizado na agenda mensal).'
    }
  }];
}

return out;

